/**
 * CareMinutes.ai — Compliance Calculator
 *
 * Implements Australian Government aged care regulations (from April 2026):
 *   - Every resident must receive 215 minutes of care per day (averaged across all residents)
 *   - Of those 215 minutes, at least 44 must come from a Registered Nurse (RN)
 *   - Staff types that count toward total: RN, EN, PCW, Agency
 *   - Only RN time counts toward the 44-minute RN minimum
 *   - Penalty: $31.64 AUD per resident per day for non-compliant days
 *
 * RAG thresholds:
 *   - RED    = below 85% of target
 *   - AMBER  = 85% to 99% of target (inclusive)
 *   - GREEN  = 100% or above target
 *
 * CRITICAL: This logic directly affects government funding calculations.
 * All edge cases are handled. Do not modify without thorough testing.
 */

/** Daily care minutes target per resident */
export const DAILY_MINUTES_PER_RESIDENT = 215;

/** Minimum RN minutes required per resident per day */
export const RN_MINUTES_PER_RESIDENT = 44;

/** Penalty per resident per non-compliant day (AUD) */
export const PENALTY_PER_RESIDENT_PER_DAY = 31.64;

/** RAG threshold — below this percentage = RED */
export const RED_THRESHOLD = 0.85;

/** RAG threshold — at or above this percentage = GREEN */
export const GREEN_THRESHOLD = 1.0;

/**
 * Determines the RAG (Red/Amber/Green) status for a given compliance percentage.
 *
 * @param {number} compliancePct - Compliance as a decimal (e.g. 0.92 = 92%)
 * @returns {'GREEN'|'AMBER'|'RED'}
 */
export function getRAGStatus(compliancePct) {
  if (compliancePct >= GREEN_THRESHOLD) return 'GREEN';
  if (compliancePct >= RED_THRESHOLD) return 'AMBER';
  return 'RED';
}

/**
 * Determines the RAG status specifically for RN minutes compliance.
 * Uses the same thresholds applied to the RN minimum (44 min/resident).
 *
 * @param {number} rnPct - RN compliance as a decimal
 * @returns {'GREEN'|'AMBER'|'RED'}
 */
export function getRNRAGStatus(rnPct) {
  return getRAGStatus(rnPct);
}

/**
 * Calculates compliance for a single day.
 *
 * @param {Array<{staffType: string, durationMinutes: number}>} shifts
 *   Array of shift objects. staffType must be one of: 'RN', 'EN', 'PCW', 'Agency'.
 *   durationMinutes is the length of the shift in minutes.
 * @param {number} residentCount - Number of residents in the facility that day.
 * @returns {{
 *   totalMinutes: number,
 *   rnMinutes: number,
 *   enMinutes: number,
 *   pcwMinutes: number,
 *   agencyMinutes: number,
 *   targetMinutes: number,
 *   rnTargetMinutes: number,
 *   compliancePct: number,
 *   rnCompliancePct: number,
 *   ragStatus: 'GREEN'|'AMBER'|'RED',
 *   rnRagStatus: 'GREEN'|'AMBER'|'RED',
 *   isCompliant: boolean,
 *   isRNCompliant: boolean,
 *   penaltyAmount: number,
 *   minutesGap: number,
 *   rnMinutesGap: number,
 * }}
 */
export function calculateDayCompliance(shifts, residentCount) {
  // Edge case: no residents — compliance is undefined, treat as non-compliant
  if (!residentCount || residentCount <= 0) {
    return {
      totalMinutes: 0,
      rnMinutes: 0,
      enMinutes: 0,
      pcwMinutes: 0,
      agencyMinutes: 0,
      targetMinutes: 0,
      rnTargetMinutes: 0,
      compliancePct: 0,
      rnCompliancePct: 0,
      ragStatus: 'RED',
      rnRagStatus: 'RED',
      isCompliant: false,
      isRNCompliant: false,
      penaltyAmount: 0,
      minutesGap: 0,
      rnMinutesGap: 0,
    };
  }

  // Edge case: no shifts logged — zero minutes delivered
  const safeShifts = Array.isArray(shifts) ? shifts : [];

  // Tally minutes by staff type
  let rnMinutes = 0;
  let enMinutes = 0;
  let pcwMinutes = 0;
  let agencyMinutes = 0;

  for (const shift of safeShifts) {
    const duration = Number(shift.durationMinutes) || 0;
    const type = (shift.staffType || '').toUpperCase();

    switch (type) {
      case 'RN':
        rnMinutes += duration;
        break;
      case 'EN':
        enMinutes += duration;
        break;
      case 'PCW':
        pcwMinutes += duration;
        break;
      case 'AGENCY RN':
        // Agency-sourced RN — counts as both RN time AND agency time
        rnMinutes += duration;
        agencyMinutes += duration;
        break;
      case 'AGENCY':
        // Agency-sourced non-RN staff — counts toward total, tracked separately
        agencyMinutes += duration;
        break;
      // Unknown staff types are excluded from compliance counting
    }
  }

  // Total care minutes: RN + EN + PCW + Agency all count
  const totalMinutes = rnMinutes + enMinutes + pcwMinutes + agencyMinutes;

  // Daily targets based on resident count
  const targetMinutes = residentCount * DAILY_MINUTES_PER_RESIDENT;
  const rnTargetMinutes = residentCount * RN_MINUTES_PER_RESIDENT;

  // Compliance percentages (capped at 2 decimal places for display)
  const compliancePct = targetMinutes > 0 ? totalMinutes / targetMinutes : 0;
  const rnCompliancePct = rnTargetMinutes > 0 ? rnMinutes / rnTargetMinutes : 0;

  // RAG status
  const ragStatus = getRAGStatus(compliancePct);
  const rnRagStatus = getRNRAGStatus(rnCompliancePct);

  // A day is compliant only if BOTH total AND RN minimums are met
  const isCompliant = compliancePct >= GREEN_THRESHOLD;
  const isRNCompliant = rnCompliancePct >= GREEN_THRESHOLD;

  // Penalty applies ONLY on RED days (below 85% of target).
  // AMBER days (85–99%) are at risk but do NOT incur a financial penalty.
  // GREEN days (100%+) are fully compliant — no penalty.
  const penaltyAmount = ragStatus === 'RED' ? residentCount * PENALTY_PER_RESIDENT_PER_DAY : 0;

  // Gaps (negative means surplus, positive means shortfall)
  const minutesGap = targetMinutes - totalMinutes;
  const rnMinutesGap = rnTargetMinutes - rnMinutes;

  return {
    totalMinutes,
    rnMinutes,
    enMinutes,
    pcwMinutes,
    agencyMinutes,
    targetMinutes,
    rnTargetMinutes,
    compliancePct,
    rnCompliancePct,
    ragStatus,
    rnRagStatus,
    isCompliant,
    isRNCompliant,
    penaltyAmount,
    minutesGap,
    rnMinutesGap,
  };
}

/**
 * Calculates compliance across a period (e.g. 14 days, a quarter).
 *
 * @param {Array<{date: string, shifts: Array}>} dailyData
 *   Array of day objects, each with a date string and shifts array.
 * @param {number} residentCount - Number of residents (assumed constant over period).
 * @returns {{
 *   days: Array,           — per-day compliance results with date attached
 *   totalDays: number,
 *   compliantDays: number,
 *   nonCompliantDays: number,
 *   overallCompliancePct: number,
 *   totalPenalty: number,
 *   averageDailyMinutes: number,
 *   averageRNMinutes: number,
 * }}
 */
export function calculatePeriodCompliance(dailyData, residentCount) {
  if (!Array.isArray(dailyData) || dailyData.length === 0) {
    return {
      days: [],
      totalDays: 0,
      compliantDays: 0,
      nonCompliantDays: 0,
      overallCompliancePct: 0,
      totalPenalty: 0,
      averageDailyMinutes: 0,
      averageRNMinutes: 0,
    };
  }

  const days = dailyData.map((day) => {
    const result = calculateDayCompliance(day.shifts, residentCount);
    return {
      date: day.date,
      ...result,
    };
  });

  const totalDays = days.length;
  const compliantDays = days.filter((d) => d.isCompliant).length;
  const nonCompliantDays = totalDays - compliantDays;

  // Overall compliance % = compliant days / total days
  const overallCompliancePct = totalDays > 0 ? compliantDays / totalDays : 0;

  const totalPenalty = days.reduce((sum, d) => sum + d.penaltyAmount, 0);

  const totalMinutesSum = days.reduce((sum, d) => sum + d.totalMinutes, 0);
  const totalRNMinutesSum = days.reduce((sum, d) => sum + d.rnMinutes, 0);

  const averageDailyMinutes = totalDays > 0 ? totalMinutesSum / totalDays : 0;
  const averageRNMinutes = totalDays > 0 ? totalRNMinutesSum / totalDays : 0;

  return {
    days,
    totalDays,
    compliantDays,
    nonCompliantDays,
    overallCompliancePct,
    totalPenalty,
    averageDailyMinutes,
    averageRNMinutes,
  };
}

/**
 * Projects the total penalty for a quarter based on current pace.
 *
 * Formula from ACQSC guidelines:
 *   projected penalty = accrued penalty + (daily non-compliance rate × days remaining × daily penalty)
 *
 * @param {{
 *   days: Array,
 *   totalPenalty: number,
 *   nonCompliantDays: number,
 *   totalDays: number,
 * }} periodData - Result from calculatePeriodCompliance for days elapsed so far.
 * @param {number} residentCount
 * @param {number} daysRemaining - Number of days left in the quarter.
 * @returns {{
 *   accruedPenalty: number,
 *   projectedAdditionalPenalty: number,
 *   projectedTotalPenalty: number,
 *   dailyPenaltyRate: number,
 *   nonComplianceRate: number,
 * }}
 */
export function projectQuarterPenalty(periodData, residentCount, daysRemaining) {
  if (!periodData || periodData.totalDays === 0) {
    return {
      accruedPenalty: 0,
      projectedAdditionalPenalty: 0,
      projectedTotalPenalty: 0,
      dailyPenaltyRate: 0,
      nonComplianceRate: 0,
    };
  }

  const accruedPenalty = periodData.totalPenalty;

  // Expected penalty per day at current pace
  const dailyPenaltyRate = residentCount * PENALTY_PER_RESIDENT_PER_DAY;

  // Penalty rate = fraction of days that actually incurred a penalty (RED days only).
  // Derived from accrued penalty rather than nonCompliantDays so that AMBER days
  // (which have penaltyAmount = 0) do not inflate the projected penalty.
  const nonComplianceRate = (periodData.totalDays > 0 && dailyPenaltyRate > 0)
    ? periodData.totalPenalty / (periodData.totalDays * dailyPenaltyRate)
    : 0;

  // Projected additional penalty for remaining days at current RED-day rate
  const projectedAdditionalPenalty = nonComplianceRate * daysRemaining * dailyPenaltyRate;

  const projectedTotalPenalty = accruedPenalty + projectedAdditionalPenalty;

  return {
    accruedPenalty,
    projectedAdditionalPenalty,
    projectedTotalPenalty,
    dailyPenaltyRate,
    nonComplianceRate,
  };
}

/**
 * Calculates how many additional minutes per day are needed for the
 * remaining days of the quarter to achieve full compliance.
 *
 * Used in the "Recovery Plan" card on the Forecast page.
 *
 * @param {number} currentTotalMinutes - Total minutes delivered so far this quarter
 * @param {number} residentCount
 * @param {number} daysElapsed - Days already passed in the quarter
 * @param {number} daysRemaining - Days left in the quarter
 * @returns {{
 *   targetTotalMinutes: number,  — total target for full quarter
 *   shortfallMinutes: number,    — how many minutes still needed
 *   additionalMinutesPerDay: number, — extra minutes needed per remaining day
 *   isOnTrack: boolean,
 * }}
 */
export function calculateRecoveryPlan(
  currentTotalMinutes,
  residentCount,
  daysElapsed,
  daysRemaining
) {
  const totalDays = daysElapsed + daysRemaining;
  const targetTotalMinutes = residentCount * DAILY_MINUTES_PER_RESIDENT * totalDays;

  const shortfallMinutes = Math.max(0, targetTotalMinutes - currentTotalMinutes);

  const additionalMinutesPerDay = daysRemaining > 0
    ? shortfallMinutes / daysRemaining
    : 0;

  const isOnTrack = shortfallMinutes === 0;

  return {
    targetTotalMinutes,
    shortfallMinutes,
    additionalMinutesPerDay,
    isOnTrack,
  };
}

/**
 * Calculates the impact of adding extra RN shifts per week on quarterly compliance.
 *
 * Used in the "What If" scenario tool on the Forecast page.
 *
 * @param {number} extraShiftsPerWeek - Number of extra RN shifts to add (1–10)
 * @param {number} shiftDurationMinutes - Average duration of each extra shift (default 480 = 8hr)
 * @param {number} daysRemaining - Days remaining in the quarter
 * @param {number} residentCount
 * @param {number} currentNonCompliantDays - Non-compliant days accrued so far
 * @param {number} currentTotalMinutes - Total minutes already delivered this quarter
 * @param {number} daysElapsed - Days elapsed in quarter so far
 * @returns {{
 *   additionalMinutesPerWeek: number,
 *   additionalMinutesPerDay: number,
 *   projectedCompliantDays: number,
 *   projectedNonCompliantDays: number,
 *   projectedCompliancePct: number,
 *   penaltySaved: number,
 * }}
 */
export function calculateWhatIfScenario(
  extraShiftsPerWeek,
  shiftDurationMinutes = 480,
  daysRemaining,
  residentCount,
  currentNonCompliantDays,
  currentTotalMinutes,
  daysElapsed
) {
  const additionalMinutesPerWeek = extraShiftsPerWeek * shiftDurationMinutes;
  const additionalMinutesPerDay = additionalMinutesPerWeek / 7;

  const dailyTarget = residentCount * DAILY_MINUTES_PER_RESIDENT;

  // Estimate how many of the remaining days would become compliant with the extra shifts
  // We base this on whether average daily minutes (improved) would meet target
  const currentAvgDaily = daysElapsed > 0 ? currentTotalMinutes / daysElapsed : 0;
  const improvedAvgDaily = currentAvgDaily + additionalMinutesPerDay;

  // For remaining days: would the improved average meet target?
  const remainingCompliantDays = improvedAvgDaily >= dailyTarget ? daysRemaining : 0;

  const totalDays = daysElapsed + daysRemaining;
  const projectedCompliantDays = Math.min(
    totalDays,
    (totalDays - currentNonCompliantDays - (daysRemaining - remainingCompliantDays))
  );
  const projectedNonCompliantDays = totalDays - projectedCompliantDays;
  const projectedCompliancePct = totalDays > 0 ? projectedCompliantDays / totalDays : 0;

  // Penalty saved = days that become compliant × daily penalty
  const dailyPenalty = residentCount * PENALTY_PER_RESIDENT_PER_DAY;
  const penaltySaved = (daysRemaining - (daysRemaining - remainingCompliantDays)) * dailyPenalty;

  return {
    additionalMinutesPerWeek,
    additionalMinutesPerDay,
    projectedCompliantDays: Math.max(0, projectedCompliantDays),
    projectedNonCompliantDays: Math.max(0, projectedNonCompliantDays),
    projectedCompliancePct: Math.min(1, Math.max(0, projectedCompliancePct)),
    penaltySaved: Math.max(0, penaltySaved),
  };
}

/**
 * Formats a currency value as AUD.
 * @param {number} amount
 * @returns {string} e.g. "$1,265.60"
 */
export function formatAUD(amount) {
  return new Intl.NumberFormat('en-AU', {
    style: 'currency',
    currency: 'AUD',
    minimumFractionDigits: 2,
  }).format(amount);
}

/**
 * Formats a compliance percentage for display.
 * @param {number} pct - Decimal (e.g. 0.92)
 * @returns {string} e.g. "92.0%"
 */
export function formatPct(pct) {
  return (pct * 100).toFixed(1) + '%';
}

'use client';

import { useState, useMemo } from 'react';
import {
  RadialBarChart, RadialBar, PolarAngleAxis, ResponsiveContainer,
  Tooltip, Cell,
} from 'recharts';
import { TrendingUp, AlertTriangle, CheckCircle } from 'lucide-react';
import { facility, shiftsByDate, trendDates } from '@/lib/dummyData';
import {
  calculatePeriodCompliance,
  projectQuarterPenalty,
  calculateRecoveryPlan,
  calculateWhatIfScenario,
  formatAUD,
  formatPct,
  PENALTY_PER_RESIDENT_PER_DAY,
} from '@/lib/compliance';

// ─── Q2 2026: 01 Apr – 30 Jun (91 days) ──────────────────────────────────────

const Q2_TOTAL_DAYS    = 91;
const Q2_ELAPSED       = 2;
const Q2_REMAINING     = Q2_TOTAL_DAYS - Q2_ELAPSED;
const Q2_START         = '2026-04-01';
const Q2_END           = '2026-06-30';

const Q2_DATES = trendDates.filter(d => d >= Q2_START);

function formatDate(iso) {
  const [y, m, d] = iso.split('-');
  return `${d}/${m}/${y}`;
}

function gaugeColour(pct) {
  if (pct >= 1)    return '#22c55e';
  if (pct >= 0.85) return '#f59e0b';
  return '#ef4444';
}

function GaugeTooltip({ active, payload }) {
  if (!active || !payload?.length) return null;
  return (
    <div className="bg-white border border-gray-200 rounded-lg shadow p-2 text-xs">
      <p className="font-semibold">{payload[0]?.value?.toFixed(1)}%</p>
    </div>
  );
}

export default function ForecastPage() {
  const [extraShifts, setExtraShifts] = useState(3);

  const q2DailyData = useMemo(() =>
    Q2_DATES.map(date => ({ date, shifts: shiftsByDate[date] || [] })),
  []);

  const q2Period = useMemo(() =>
    calculatePeriodCompliance(q2DailyData, facility.residentCount),
  [q2DailyData]);

  const projection = useMemo(() =>
    projectQuarterPenalty(q2Period, facility.residentCount, Q2_REMAINING),
  [q2Period]);

  const totalMinutesSoFar = q2Period.days.reduce((a, d) => a + d.totalMinutes, 0);
  const recovery = useMemo(() =>
    calculateRecoveryPlan(totalMinutesSoFar, facility.residentCount, Q2_ELAPSED, Q2_REMAINING),
  [totalMinutesSoFar]);

  const whatIf = useMemo(() =>
    calculateWhatIfScenario(
      extraShifts, 480, Q2_REMAINING, facility.residentCount,
      q2Period.nonCompliantDays, totalMinutesSoFar, Q2_ELAPSED,
    ),
  [extraShifts, q2Period.nonCompliantDays, totalMinutesSoFar]);

  const compliancePct = q2Period.overallCompliancePct;
  const gaugeValue    = Math.min(compliancePct * 100, 100);
  const gaugeData     = [{ name: 'Compliance', value: gaugeValue, fill: gaugeColour(compliancePct) }];

  const penaltyRows = q2Period.days.filter(d => d.ragStatus === 'RED').map(d => ({
    date:       formatDate(d.date),
    status:     d.ragStatus,
    residents:  facility.residentCount,
    penaltyDay: PENALTY_PER_RESIDENT_PER_DAY,
    total:      d.penaltyAmount,
  }));

  return (
    <div className="p-4 md:p-6 max-w-7xl mx-auto">

      {/* ── Header ── */}
      <div className="mb-6">
        <h1 className="text-xl font-bold text-gray-900">Quarterly Forecast</h1>
        <p className="text-sm text-gray-500 mt-0.5">Q2 2026 — April to June · {formatDate(Q2_START)} – {formatDate(Q2_END)}</p>
      </div>

      {/* ── Summary Cards ── */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 md:gap-4 mb-6">
        <div className={`rounded-xl shadow-sm border border-gray-100 p-4 md:p-5 card-hover ${compliancePct >= 1 ? 'stat-gradient-green' : compliancePct >= 0.85 ? 'stat-gradient-amber' : 'stat-gradient-red'}`}>
          <p className="text-xs font-medium text-gray-500 uppercase tracking-wide">Quarter Compliance</p>
          <p className={`text-xl md:text-2xl font-bold mt-1 ${compliancePct >= 1 ? 'text-green-600' : compliancePct >= 0.85 ? 'text-amber-600' : 'text-red-600'}`}>
            {formatPct(compliancePct)}
          </p>
          <p className="text-xs text-gray-400 mt-0.5">{Q2_ELAPSED} days so far</p>
        </div>
        <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-4 md:p-5 card-hover">
          <p className="text-xs font-medium text-gray-500 uppercase tracking-wide">Days Remaining</p>
          <p className="text-xl md:text-2xl font-bold mt-1 text-gray-900">{Q2_REMAINING}</p>
          <p className="text-xs text-gray-400 mt-0.5">of {Q2_TOTAL_DAYS} days</p>
        </div>
        <div className={`rounded-xl shadow-sm border border-gray-100 p-4 md:p-5 card-hover ${q2Period.totalPenalty > 0 ? 'stat-gradient-red' : 'stat-gradient-green'}`}>
          <p className="text-xs font-medium text-gray-500 uppercase tracking-wide">Penalty Accrued</p>
          <p className={`text-xl md:text-2xl font-bold mt-1 ${q2Period.totalPenalty > 0 ? 'text-red-600' : 'text-green-600'}`}>
            {formatAUD(q2Period.totalPenalty)}
          </p>
          <p className="text-xs text-gray-400 mt-0.5">{q2Period.days.filter(d => d.ragStatus === 'RED').length} RED days</p>
        </div>
        <div className={`rounded-xl shadow-sm border border-gray-100 p-4 md:p-5 card-hover ${projection.projectedTotalPenalty > 0 ? 'stat-gradient-red' : 'stat-gradient-green'}`}>
          <p className="text-xs font-medium text-gray-500 uppercase tracking-wide">Projected Penalty</p>
          <p className={`text-xl md:text-2xl font-bold mt-1 ${projection.projectedTotalPenalty > 0 ? 'text-red-600' : 'text-green-600'}`}>
            {formatAUD(projection.projectedTotalPenalty)}
          </p>
          <p className="text-xs text-gray-400 mt-0.5">at current pace</p>
        </div>
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-4 md:gap-6">

        {/* ── Left: Gauge + Penalty Table ── */}
        <div className="xl:col-span-2 space-y-4 md:space-y-6">

          {/* Compliance Gauge */}
          <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-4 md:p-5 card-hover">
            <h2 className="font-semibold text-gray-900 mb-1">Q2 Compliance Gauge</h2>
            <p className="text-xs text-gray-400 mb-4">Based on {Q2_ELAPSED} days of data — updates daily</p>
            <div className="flex flex-col sm:flex-row items-center gap-6">
              <div className="w-40 h-40 md:w-48 md:h-48 relative flex-shrink-0">
                <ResponsiveContainer width="100%" height="100%">
                  <RadialBarChart
                    cx="50%" cy="50%"
                    innerRadius="65%" outerRadius="85%"
                    startAngle={180} endAngle={-180}
                    data={gaugeData}
                    barSize={18}
                  >
                    <PolarAngleAxis type="number" domain={[0, 100]} angleAxisId={0} tick={false} />
                    <RadialBar
                      background={{ fill: '#f1f5f9' }}
                      dataKey="value"
                      angleAxisId={0}
                      cornerRadius={6}
                    >
                      {gaugeData.map((entry, i) => (
                        <Cell key={i} fill={entry.fill} />
                      ))}
                    </RadialBar>
                    <Tooltip content={<GaugeTooltip />} />
                  </RadialBarChart>
                </ResponsiveContainer>
                <div className="absolute inset-0 flex flex-col items-center justify-center">
                  <span className="text-2xl md:text-3xl font-bold" style={{ color: gaugeColour(compliancePct) }}>
                    {gaugeValue.toFixed(0)}%
                  </span>
                  <span className="text-xs text-gray-400 mt-0.5">compliant</span>
                </div>
              </div>
              <div className="flex-1 space-y-3 w-full">
                <div className="flex items-center gap-3">
                  <span className="w-3 h-3 rounded-full bg-[#22c55e] shrink-0" />
                  <div className="flex-1 min-w-0">
                    <p className="text-xs text-gray-500">Compliant days</p>
                    <p className="font-semibold text-gray-900 text-sm">{q2Period.compliantDays} / {Q2_ELAPSED} days ({formatPct(compliancePct)})</p>
                  </div>
                </div>
                <div className="flex items-center gap-3">
                  <span className="w-3 h-3 rounded-full bg-[#ef4444] shrink-0" />
                  <div className="flex-1 min-w-0">
                    <p className="text-xs text-gray-500">Non-compliant days</p>
                    <p className="font-semibold text-gray-900 text-sm">{q2Period.nonCompliantDays} days so far</p>
                  </div>
                </div>
                <div className="flex items-center gap-3">
                  <span className="w-3 h-3 rounded-full bg-[#f59e0b] shrink-0" />
                  <div className="flex-1 min-w-0">
                    <p className="text-xs text-gray-500">Projected non-compliant</p>
                    <p className="font-semibold text-gray-900 text-sm">
                      ~{Math.round(projection.nonComplianceRate * Q2_TOTAL_DAYS)} days for full quarter
                    </p>
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* Penalty Breakdown Table */}
          <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden card-hover">
            <div className="px-4 md:px-5 py-4 border-b border-gray-100">
              <h2 className="font-semibold text-gray-900">Penalty Breakdown</h2>
              <p className="text-xs text-gray-400 mt-0.5">Non-compliant days in Q2 2026 so far</p>
            </div>
            {penaltyRows.length === 0 ? (
              <div className="py-12 text-center">
                <CheckCircle className="w-8 h-8 text-green-500 mx-auto mb-2" />
                <p className="text-sm text-gray-500 font-medium">No penalties recorded this quarter</p>
                <p className="text-xs text-gray-400 mt-1">All days compliant so far</p>
              </div>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full text-sm min-w-[480px]">
                  <thead>
                    <tr className="bg-gray-50 border-b border-gray-100">
                      {['Date','Status','Residents','Penalty/Resident','Total Penalty'].map(h => (
                        <th key={h} className="text-left px-3 md:px-4 py-3 text-xs font-semibold text-gray-500 uppercase tracking-wide whitespace-nowrap">{h}</th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {penaltyRows.map((row, i) => (
                      <tr key={i} className={`border-b border-gray-50 hover:bg-red-50/30 transition-colors ${i % 2 === 1 ? 'bg-gray-50/40' : ''}`}>
                        <td className="px-3 md:px-4 py-3 font-medium text-gray-900">{row.date}</td>
                        <td className="px-3 md:px-4 py-3">
                          <span className={`px-2 py-0.5 rounded text-xs font-bold ${
                            row.status === 'RED' ? 'bg-red-100 text-red-700' : 'bg-amber-100 text-amber-700'
                          }`}>{row.status}</span>
                        </td>
                        <td className="px-3 md:px-4 py-3 text-gray-700">{row.residents}</td>
                        <td className="px-3 md:px-4 py-3 text-gray-700">{formatAUD(row.penaltyDay)}</td>
                        <td className="px-3 md:px-4 py-3 font-semibold text-red-600">{formatAUD(row.total)}</td>
                      </tr>
                    ))}
                    <tr className="bg-red-50 border-t border-red-100">
                      <td colSpan={4} className="px-3 md:px-4 py-3 font-semibold text-gray-700">Total Penalties (Q2 so far)</td>
                      <td className="px-3 md:px-4 py-3 font-bold text-red-700">{formatAUD(q2Period.totalPenalty)}</td>
                    </tr>
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </div>

        {/* ── Right: Recovery Plan + What If ── */}
        <div className="space-y-4 md:space-y-6">

          {/* Recovery Plan */}
          <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-4 md:p-5 card-hover">
            <div className="flex items-center gap-2 mb-4">
              {recovery.isOnTrack
                ? <CheckCircle className="w-4 h-4 text-green-600" />
                : <AlertTriangle className="w-4 h-4 text-amber-600" />
              }
              <h2 className="font-semibold text-gray-900">Recovery Plan</h2>
            </div>
            {recovery.isOnTrack ? (
              <div className="bg-green-50 border border-green-200 rounded-lg p-3">
                <p className="text-sm text-green-700 font-medium">You are on track for Q2 2026! 🎉</p>
                <p className="text-xs text-green-600 mt-1">Continue current staffing levels to maintain compliance.</p>
              </div>
            ) : (
              <div className="space-y-3">
                <div className="bg-amber-50 border border-amber-200 rounded-lg p-3">
                  <p className="text-sm text-amber-800 font-semibold">
                    {Math.round(recovery.additionalMinutesPerDay).toLocaleString()} additional minutes/day needed
                  </p>
                  <p className="text-xs text-amber-700 mt-1">
                    for the remaining {Q2_REMAINING} days to meet Q2 target.
                  </p>
                </div>
                <div className="space-y-2 text-sm">
                  {[
                    { label: 'Q2 total target',    value: `${recovery.targetTotalMinutes.toLocaleString()} min`, colour: 'text-gray-900' },
                    { label: 'Minutes delivered',   value: `${totalMinutesSoFar.toLocaleString()} min`,          colour: 'text-gray-900' },
                    { label: 'Shortfall',           value: `${recovery.shortfallMinutes.toLocaleString()} min`,  colour: 'text-red-600'  },
                    { label: 'Extra shifts needed', value: `~${Math.ceil(recovery.additionalMinutesPerDay / 480)} shifts/day`, colour: 'text-amber-600' },
                  ].map(({ label, value, colour }) => (
                    <div key={label} className="flex justify-between py-1 border-b border-gray-50 last:border-0 gap-2">
                      <span className="text-gray-500 shrink-0">{label}</span>
                      <span className={`font-semibold ${colour}`}>{value}</span>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>

          {/* What If Scenario */}
          <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-4 md:p-5 card-hover">
            <h2 className="font-semibold text-gray-900 mb-1">What If Scenario</h2>
            <p className="text-xs text-gray-400 mb-4">Slide to see impact of adding extra RN shifts</p>

            <div className="mb-4">
              <div className="flex justify-between items-center mb-2">
                <label className="text-sm font-medium text-gray-700">Extra RN shifts/week</label>
                <span className="text-lg font-bold text-[#22c55e]">{extraShifts}</span>
              </div>
              <input
                type="range"
                min={1} max={10} step={1}
                value={extraShifts}
                onChange={e => setExtraShifts(Number(e.target.value))}
                className="w-full h-2 bg-gray-200 rounded-full appearance-none cursor-pointer accent-[#22c55e]"
              />
              <div className="flex justify-between text-xs text-gray-400 mt-1">
                <span>1</span>
                <span>10</span>
              </div>
            </div>

            <div className="space-y-1 text-sm">
              {[
                { label: 'Additional minutes/week',      value: `${whatIf.additionalMinutesPerWeek.toLocaleString()} min`,           colour: 'text-gray-900' },
                { label: 'Projected compliance',          value: formatPct(whatIf.projectedCompliancePct),                            colour: whatIf.projectedCompliancePct >= 1 ? 'text-green-600' : whatIf.projectedCompliancePct >= 0.85 ? 'text-amber-600' : 'text-red-600' },
                { label: 'Projected non-compliant days',  value: String(whatIf.projectedNonCompliantDays),                            colour: 'text-gray-900' },
                { label: 'Penalty saved',                 value: whatIf.penaltySaved > 0 ? `+ ${formatAUD(whatIf.penaltySaved)}` : '$0.00', colour: whatIf.penaltySaved > 0 ? 'text-green-600' : 'text-gray-400' },
              ].map(({ label, value, colour }) => (
                <div key={label} className="flex justify-between items-center py-2 border-b border-gray-50 last:border-0 gap-2">
                  <span className="text-gray-500 shrink-0 text-xs">{label}</span>
                  <span className={`font-bold text-sm ${colour}`}>{value}</span>
                </div>
              ))}
            </div>

            {whatIf.projectedCompliancePct >= 1 && (
              <div className="mt-4 bg-green-50 border border-green-200 rounded-lg p-3">
                <p className="text-xs text-green-700 font-medium flex items-center gap-1.5">
                  <TrendingUp className="w-3.5 h-3.5 shrink-0" />
                  Adding {extraShifts} extra RN shift{extraShifts > 1 ? 's' : ''}/week would achieve full Q2 compliance.
                </p>
              </div>
            )}
          </div>

        </div>
      </div>
    </div>
  );
}

